const a1GrammarAnswerBank = [
  ...a1GrammarLessonData.map(([, , , , , , , answer]) => answer),
  ...Object.values(a1GrammarAdditionalQuestionData).flatMap((questions) => questions.map(([, answer]) => answer)),
  ...Object.values(a1GrammarOriginalQuestionData).map(([, answer]) => answer),
];

const a1GrammarLessons = a1GrammarLessonData.map(([id, title, sourcePages, goal, rule, cardTitle, prompt, answer, feedback], lessonIndex) => {
  const additionalQuestions = a1GrammarAdditionalQuestionData[id];
  const originalQuestion = a1GrammarOriginalQuestionData[id];
  const keyedAnswers = [answer, ...additionalQuestions.map(([, extraAnswer]) => extraAnswer)];
  const originalChoices = [originalQuestion[1], ...new Set([...keyedAnswers, ...a1GrammarAnswerBank].filter((choice) => choice !== originalQuestion[1]))].slice(0, 3);
  const choiceOffset = lessonIndex % originalChoices.length;
  const choices = originalChoices.slice(choiceOffset).concat(originalChoices.slice(0, choiceOffset));

  return {
    id,
    title,
    sourcePages,
    goal,
    explanation: [rule],
    cards: [{ title: cardTitle, text: rule, tone: 'lilac' }],
    questions: [
      { type: 'text', prompt, answer, explanation: feedback },
      ...additionalQuestions.map(([extraPrompt, extraAnswer, extraFeedback]) => ({
        type: 'text',
        prompt: extraPrompt,
        answer: extraAnswer,
        explanation: extraFeedback,
      })),
      { type: 'text', prompt: originalQuestion[0], answer: originalQuestion[1], explanation: originalQuestion[2] },
      { type: 'choice', prompt: originalQuestion[0], choices, answer: originalQuestion[1], explanation: originalQuestion[2] },
    ],
  };
});

